import urllib.parse
import json

query = "multi agent orchestration llm"
encoded = urllib.parse.quote_plus(query)
goto_url(f"https://scholar.google.com/scholar?q={encoded}&hl=en")
wait_for_load()

res = js("""
Array.from(document.querySelectorAll('.gs_ri')).slice(0, 7).map(el => {
  const titleEl = el.querySelector('.gs_rt a');
  const pubEl = el.querySelector('.gs_a');
  const snippetEl = el.querySelector('.gs_rs');
  return {
    title: titleEl ? titleEl.innerText : (el.querySelector('.gs_rt') ? el.querySelector('.gs_rt').innerText : ''),
    link: titleEl ? titleEl.href : '',
    authors: pubEl ? pubEl.innerText : '',
    snippet: snippetEl ? snippetEl.innerText : ''
  };
})
""")
print(json.dumps(res, indent=2))

goto_url("https://arxiv.org/search/?query=multi-agent+orchestration+llm&searchtype=all&source=header")
wait_for_load()

res = js("""
Array.from(document.querySelectorAll('.arxiv-result')).slice(0, 6).map(el => {
  const titleEl = el.querySelector('.title');
  const authorsEl = el.querySelector('.authors');
  const abstractEl = el.querySelector('.abstract-full');
  const shortAbstractEl = el.querySelector('.abstract-short');
  const linkEl = el.querySelector('.list-title a');
  return {
    title: titleEl ? titleEl.innerText.replace(/^Title:\s*/, '').trim() : '',
    link: linkEl ? linkEl.href : '',
    authors: authorsEl ? authorsEl.innerText.replace(/^Authors:\s*/, '').trim() : '',
    summary: abstractEl ? abstractEl.innerText.trim() : (shortAbstractEl ? shortAbstractEl.innerText.trim() : '')
  };
})
""")
import json
print(json.dumps(res, indent=2))

